package net.officefloor.hq.app.person;

import jakarta.persistence.CollectionTable;
import jakarta.persistence.Column;
import jakarta.persistence.ElementCollection;
import jakarta.persistence.Entity;
import jakarta.persistence.FetchType;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.JoinColumn;
import jakarta.persistence.Table;
import jakarta.persistence.Version;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Objects;
import net.officefloor.hq.app.claim.ClaimStatus;

/**
 * A person on a sheet, with a name (unique on the sheet, ignoring case) and a dated grade (A, B or C): each grade
 * applies from its from-date, the first one given from the beginning of time.
 */
@Entity
@Table(name = "person")
public class Person {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "name", nullable = false)
    private String name;

    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "person_grade", joinColumns = @JoinColumn(name = "person_id"))
    private List<DatedGrade> grades = new ArrayList<>();

    @Column(name = "retired_from")
    private LocalDate retiredFrom;

    @Column(name = "held", nullable = false)
    private boolean held;

    @Version
    @Column(name = "version", nullable = false)
    private long version;

    protected Person() {
    }

    public Person(String sheetId, String name, String grade) {
        this.sheetId = sheetId;
        this.name = name;
        this.grades.add(new DatedGrade(grade, null));
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public String getName() {
        return name;
    }

    public void setName(String name) {
        this.name = name;
    }

    /** Every grade recorded for the person, earliest from-date first (the one from the beginning of time first). */
    public List<DatedGrade> getGrades() {
        return grades.stream().sorted(Comparator.comparing(DatedGrade::getFrom,
                Comparator.nullsFirst(Comparator.naturalOrder()))).toList();
    }

    /** The grade in force on the date: the one with the latest from-date on or before it. */
    public String gradeOn(LocalDate date) {
        return grades.stream().filter(g -> g.getFrom() == null || (date != null && !g.getFrom().isAfter(date)))
                .max(Comparator.comparing(DatedGrade::getFrom, Comparator.nullsFirst(Comparator.naturalOrder())))
                .map(DatedGrade::getGrade).orElse(null);
    }

    /** Records the grade from the date, replacing one already recorded from that same date; the others are kept. */
    public void recordGrade(String grade, LocalDate from) {
        grades.removeIf(g -> Objects.equals(g.getFrom(), from));
        grades.add(new DatedGrade(grade, from));
    }

    /** The date the person is retired from; null while they are not retired. */
    public LocalDate getRetiredFrom() {
        return retiredFrom;
    }

    public void setRetiredFrom(LocalDate retiredFrom) {
        this.retiredFrom = retiredFrom;
    }

    /** A person with a retirement date set is retired at once, whatever the date. */
    public boolean isRetired() {
        return retiredFrom != null;
    }

    /** Whether the person is on hold: while held, their open (and pending) claims count in no live total. */
    public boolean isHeld() {
        return held;
    }

    public void setHeld(boolean held) {
        this.held = held;
    }

    /** Whether the claim of the given status counts toward the person's live totals: an open one not while held. */
    public boolean countsLive(ClaimStatus status) {
        return status.counts() && !(held && status.isOpen());
    }

    /** The version of the person as stored, raised on each save. */
    public long getVersion() {
        return version;
    }
}
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.http.HttpStatus;
import org.springframework.orm.ObjectOptimisticLockingFailureException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

/** The people kept on a sheet. */
@Service
public class PersonService {

    private final PersonRepository people;
    private final PatronRepository patrons;
    private final SheetService sheets;
    private final RollupService rollup;
    private final Audit audit;

    public PersonService(PersonRepository people, PatronRepository patrons, SheetService sheets, RollupService rollup, Audit audit) {
        this.people = people;
        this.patrons = patrons;
        this.sheets = sheets;
        this.rollup = rollup;
        this.audit = audit;
    }

    @Transactional(readOnly = true)
    public List<Person> list(String sheetId) {
        return people.findBySheetIdOrderByIdAsc(sheetId);
    }

    /** The sheet's today, which the grade a person is listed with is in force on. */
    @Transactional
    public LocalDate today(String sheetId) {
        return sheets.load(sheetId).getToday();
    }

    /** Adds the person; the grade they are given first applies from the beginning of time. */
    @Transactional
    public Person add(String by, String sheetId, String name, String grade) {
        sheets.load(sheetId);
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        String trimmed = name.strip();
        if (people.existsBySheetIdAndNameIgnoreCase(sheetId, trimmed)) {
            throw nameInUse();
        }
        Person added = save(new Person(sheetId, trimmed, grade));
        audit.recordOnCommit(record("PERSON_ADDED", by, added, today(sheetId)));
        rollup.recordChanges(by, sheetId, before);
        return added;
    }

    /**
     * Saves an edit made from the given version of the person; refused when it has been saved since. The grade is
     * recorded from the from-date (missing: the sheet's today), keeping the ones already recorded, except that an
     * edit leaving the grade in force today as it is, with no from-date, records nothing.
     */
    @Transactional
    public Person update(String by, String sheetId, Long id, long version, String name, String grade,
            LocalDate gradeFrom) {
        LocalDate today = today(sheetId);
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        Person person = people.findByIdAndSheetId(id, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person."));
        if (person.getVersion() != version) {
            throw stale();
        }
        String trimmed = name.strip();
        if (people.existsBySheetIdAndNameIgnoreCaseAndIdNot(sheetId, trimmed, id)) {
            throw nameInUse();
        }
        person.setName(trimmed);
        if (gradeFrom != null || !grade.equals(person.gradeOn(today))) {
            person.recordGrade(grade, gradeFrom != null ? gradeFrom : today);
        }
        Person saved = save(person);
        audit.recordOnCommit(record("PERSON_EDITED", by, saved, today));
        rollup.recordChanges(by, sheetId, before);
        return saved;
    }

    /** Retires the person from the date; a missing date takes the sheet's today. Their claims keep counting. */
    @Transactional
    public Person retire(String by, String sheetId, Long id, LocalDate from) {
        LocalDate on = from != null ? from : sheets.load(sheetId).getToday();
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        Person person = people.findWithLockByIdAndSheetId(id, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person."));
        person.setRetiredFrom(on);
        Person saved = save(person);
        audit.recordOnCommit("PERSON_RETIRED sheet=" + sheetId + " by=" + by + " name=" + saved.getName()
                + " from=" + on);
        rollup.recordChanges(by, sheetId, before);
        return saved;
    }

    /** Puts the person on hold, or releases them when held. While held, their open claims count in no live total. */
    @Transactional
    public Person toggleHold(String by, String sheetId, Long id) {
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        Person person = people.findWithLockByIdAndSheetId(id, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person."));
        person.setHeld(!person.isHeld());
        Person saved = save(person);
        audit.recordOnCommit((saved.isHeld() ? "PERSON_HELD" : "PERSON_RELEASED") + " sheet=" + sheetId + " by=" + by
                + " name=" + saved.getName());
        rollup.recordChanges(by, sheetId, before);
        return saved;
    }

    @Transactional(readOnly = true)
    public List<Patron> patrons(String sheetId) {
        return patrons.findBySheetIdOrderByIdAsc(sheetId);
    }

    /** Names another person on the sheet as the person's patron; never themselves, nor anyone twice. */
    @Transactional
    public Patron addPatron(String by, String sheetId, Long id, Long patronId) {
        Person person = people.findWithLockByIdAndSheetId(id, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person."));
        Person patron = people.findByIdAndSheetId(patronId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such patron."));
        if (person.getId().equals(patron.getId())) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A person cannot be their own patron.");
        }
        if (patrons.existsByPersonIdAndPatronId(person.getId(), patron.getId())) {
            throw patronNamed();
        }
        Patron added;
        try {
            added = patrons.saveAndFlush(new Patron(sheetId, person.getId(), patron.getId()));
        } catch (DataIntegrityViolationException e) {
            throw patronNamed();
        }
        audit.recordOnCommit("PATRON_ADDED sheet=" + sheetId + " by=" + by + " name=" + person.getName()
                + " patron=" + patron.getName());
        return added;
    }

    /** Saves the person; the store's unique index refuses a name another request took meanwhile. */
    private Person save(Person person) {
        try {
            return people.saveAndFlush(person);
        } catch (DataIntegrityViolationException e) {
            throw nameInUse();
        } catch (ObjectOptimisticLockingFailureException e) {
            // another request saved the person between this one reading and writing it
            throw stale();
        }
    }

    /** The audit line about a person, with the grade in force on the sheet's today. */
    private static String record(String event, String by, Person p, LocalDate today) {
        return event + " sheet=" + p.getSheetId() + " by=" + by + " name=" + p.getName() + " grade="
                + p.gradeOn(today);
    }

    private static ResponseStatusException stale() {
        return new ResponseStatusException(HttpStatus.PRECONDITION_FAILED,
                "Someone else has saved this person since it was opened.");
    }

    private static ResponseStatusException patronNamed() {
        return new ResponseStatusException(HttpStatus.CONFLICT, "That person is already one of their patrons.");
    }

    private static ResponseStatusException nameInUse() {
        return new ResponseStatusException(HttpStatus.CONFLICT, "That name is already in use on this sheet.");
    }
}
package net.officefloor.hq.app.person;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.session.SessionController;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;
import org.springframework.web.bind.annotation.SessionAttribute;

@RestController
@Validated
@RequestMapping("/api/sheets/{sheetId}/people")
public class PersonController {

    /** A person as listed: the grade is the one in force on the sheet's today, the grades every one recorded. */
    public record PersonView(Long id, String name, String grade, List<GradeView> grades, long version,
            LocalDate retiredFrom, boolean held) {
        public static PersonView of(Person p, LocalDate today) {
            return new PersonView(p.getId(), p.getName(), p.gradeOn(today),
                    p.getGrades().stream().map(GradeView::of).toList(), p.getVersion(), p.getRetiredFrom(),
                    p.isHeld());
        }
    }

    /** A grade a person has from its from-date (null: from the beginning of time). */
    public record GradeView(String grade, LocalDate from) {
        public static GradeView of(DatedGrade g) {
            return new GradeView(g.getGrade(), g.getFrom());
        }
    }

    /** A person's fields as the form submits them; the name is stored without surrounding spaces. */
    public record PersonForm(@NotBlank @Size(max = 200) String name,
            @NotNull @Pattern(regexp = "[ABC]") String grade) {
    }

    /**
     * An edit of a person: its fields, the date its grade applies from (missing: the sheet's today) and the version
     * of the person the editor loaded.
     */
    public record PersonEdit(@NotBlank @Size(max = 200) String name,
            @NotNull @Pattern(regexp = "[ABC]") String grade, LocalDate gradeFrom, @NotNull Long version) {
    }

    /** One person named as another's patron. */
    public record PatronView(Long id, Long personId, Long patronId) {
        public static PatronView of(Patron p) {
            return new PatronView(p.getId(), p.getPersonId(), p.getPatronId());
        }
    }

    /** A patron to add: the id of another person on the sheet. */
    public record PatronForm(@NotNull Long patronId) {
    }

    /** A retirement: the date it takes effect; a missing date takes the sheet's today. */
    public record RetireForm(LocalDate from) {
    }

    private final PersonService service;

    public PersonController(PersonService service) {
        this.service = service;
    }

    /** All the people on the sheet, in the order they were added. */
    @GetMapping
    public List<PersonView> list(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9_.-]+") String sheetId) {
        LocalDate today = service.today(sheetId);
        return service.list(sheetId).stream().map(p -> PersonView.of(p, today)).toList();
    }

    @PostMapping
    public PersonView add(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9_.-]+") String sheetId,
            @Valid @RequestBody PersonForm form,
            @SessionAttribute(SessionController.USER) String user) {
        return view(sheetId, service.add(user, sheetId, form.name(), form.grade()));
    }

    @PutMapping("/{id}")
    public PersonView update(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9_.-]+") String sheetId,
            @PathVariable Long id, @Valid @RequestBody PersonEdit form,
            @SessionAttribute(SessionController.USER) String user) {
        return view(sheetId,
                service.update(user, sheetId, id, form.version(), form.name(), form.grade(), form.gradeFrom()));
    }

    @PostMapping("/{id}/retire")
    public PersonView retire(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9_.-]+") String sheetId,
            @PathVariable Long id, @RequestBody RetireForm form,
            @SessionAttribute(SessionController.USER) String user) {
        return view(sheetId, service.retire(user, sheetId, id, form.from()));
    }

    /** Puts the person on hold, or takes them off hold when they are held. */
    @PostMapping("/{id}/hold")
    public PersonView hold(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9_.-]+") String sheetId,
            @PathVariable Long id, @SessionAttribute(SessionController.USER) String user) {
        return view(sheetId, service.toggleHold(user, sheetId, id));
    }

    /** The person as listed on the sheet's today. */
    private PersonView view(String sheetId, Person person) {
        return PersonView.of(person, service.today(sheetId));
    }

    /** Every patron named on the sheet, in the order they were named. */
    @GetMapping("/patrons")
    public List<PatronView> patrons(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9_.-]+") String sheetId) {
        return service.patrons(sheetId).stream().map(PatronView::of).toList();
    }

    /** Names another person on the sheet as the person's patron; refused for themselves or one already named. */
    @PostMapping("/{id}/patrons")
    public PatronView addPatron(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9_.-]+") String sheetId,
            @PathVariable Long id, @Valid @RequestBody PatronForm form,
            @SessionAttribute(SessionController.USER) String user) {
        return PatronView.of(service.addPatron(user, sheetId, id, form.patronId()));
    }
}
package net.officefloor.hq.app.rollup;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Set;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.claim.ClaimService;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.stereotype.Service;

/**
 * The figures a sheet shows: each person's claimed and due-total, and the sheet's totals. A change takes a
 * {@link #snapshot} before it and calls {@link #recordChanges} after it, so the audit gets one ROLLUP line per person
 * whose figures moved (in the order they were added) and a TOTALS line when the sheet's totals moved.
 */
@Service
public class RollupService {

    /** One person's figures; a null due-total is n/a. */
    public record Figures(String name, BigDecimal claimed, BigDecimal dueTotal) {
    }

    /** The figures of every person on a sheet, by person id in the order they were added, and the sheet's totals. */
    public record Snapshot(Map<Long, Figures> people, BigDecimal claimedTotal, BigDecimal dueTotal) {
    }

    private static final BigDecimal ZERO = BigDecimal.ZERO.setScale(2);

    private final PersonRepository people;
    private final ClaimRepository claims;
    private final RateRepository rates;
    private final SheetRepository sheets;
    private final Audit audit;

    public RollupService(PersonRepository people, ClaimRepository claims, RateRepository rates, SheetRepository sheets,
            Audit audit) {
        this.people = people;
        this.claims = claims;
        this.rates = rates;
        this.sheets = sheets;
        this.audit = audit;
    }

    /** The sheet's figures as the store holds them now (as the screen computes them). */
    public Snapshot snapshot(String sheetId) {
        claims.flush();
        Sheet sheet = sheets.findById(sheetId).orElse(null);
        LocalDate today = sheet == null ? null : sheet.getToday();
        BigDecimal floor = sheet == null ? null : sheet.getFloor();
        Map<String, List<Rate>> byGrade = new HashMap<>();
        for (Rate r : rates.findBySheetIdOrderByGradeAscFromAsc(sheetId)) {
            byGrade.computeIfAbsent(r.getGrade(), g -> new ArrayList<>()).add(r);
        }
        Map<Long, List<Claim>> claimsBy = new HashMap<>();
        for (Claim c : claims.findBySheetIdOrderByIdDesc(sheetId)) {
            if (c.getStatus().counts()) {
                claimsBy.computeIfAbsent(c.getPersonId(), id -> new ArrayList<>()).add(c);
            }
        }
        Map<Long, Figures> figures = new LinkedHashMap<>();
        BigDecimal claimedTotal = ZERO;
        BigDecimal dueTotal = ZERO;
        for (Person p : people.findBySheetIdOrderByIdAsc(sheetId)) {
            // while the person is held, their open and pending claims count in no live total
            List<Claim> counted = claimsBy.getOrDefault(p.getId(), List.of()).stream()
                    .filter(c -> p.countsLive(c.getStatus())).toList();
            BigDecimal claimed = ZERO;
            BigDecimal due = ZERO;
            boolean kept = false;
            // the grades whose rate today decides n/a: the one in force today and each counted claim's
            Set<String> grades = new HashSet<>();
            grades.add(p.gradeOn(today));
            for (Claim c : counted) {
                grades.add(p.gradeOn(c.getDate()));
                claimed = claimed.add(c.getAmount());
                kept |= c.getSettledDue() != null || (c.isBound() && c.getStatedDue() != null);
                // the claim's rate is the one its person's grade in force on its date has
                BigDecimal figure = figure(c, byGrade.getOrDefault(p.gradeOn(c.getDate()), List.of()), floor, sheet);
                if (c.getStatus().isOpen() && !c.isCorrection()) {
                    figure = ClaimService.withLateCharge(figure, c, sheet);
                }
                if (figure != null) {
                    due = due.add(figure);
                }
            }
            // with no rate in force today for any of those grades and no kept figure, the due-total is n/a
            if (!kept && (today == null || grades.stream()
                    .allMatch(g -> inForce(byGrade.getOrDefault(g, List.of()), today) == null))) {
                due = null;
            }
            figures.put(p.getId(), new Figures(p.getName(), claimed, due));
            claimedTotal = claimedTotal.add(claimed);
            if (due != null) {
                dueTotal = dueTotal.add(due);
            }
        }
        return new Snapshot(figures, claimedTotal, dueTotal);
    }

    /**
     * Records, once the change commits, a ROLLUP line for each person whose figures differ from the snapshot taken
     * before the change (a person new since then counts as changed), then a TOTALS line when the sheet's totals moved.
     */
    public void recordChanges(String by, String sheetId, Snapshot before) {
        Snapshot after = snapshot(sheetId);
        String head = " sheet=" + sheetId + " by=" + by;
        for (Map.Entry<Long, Figures> e : after.people().entrySet()) {
            Figures was = before.people().get(e.getKey());
            Figures now = e.getValue();
            if (was != null && was.claimed().equals(now.claimed()) && Objects.equals(was.dueTotal(), now.dueTotal())) {
                continue;
            }
            audit.recordOnCommit("ROLLUP" + head + " person=" + now.name() + " claimed=" + now.claimed().toPlainString()
                    + " due-total=" + text(now.dueTotal()));
        }
        if (!before.claimedTotal().equals(after.claimedTotal()) || !before.dueTotal().equals(after.dueTotal())) {
            audit.recordOnCommit("TOTALS" + head + " claimed-total=" + after.claimedTotal().toPlainString()
                    + " due-total=" + after.dueTotal().toPlainString());
        }
    }

    /**
     * The figure a claim totals: its settled due, else the one a statement bound it to, else live (floored, unless
     * it is a correction), rounded as the sheet's policy date decides for it.
     */
    private static BigDecimal figure(Claim c, List<Rate> rates, BigDecimal floor, Sheet sheet) {
        if (c.getSettledDue() != null) {
            return c.getSettledDue();
        }
        if (c.isBound()) {
            return c.getStatedDue();
        }
        Rate rate = inForce(rates, c.getDate());
        return rate == null ? null : ClaimService.floored(ClaimService.dueOn(c.getAmount(), rate.getPct(), sheet.roundingOn(c.getRoundsOn())),
                c.isCorrection() ? null : floor);
    }

    /** The rate in force on the date: the one with the latest from-date on or before it; null with none. */
    private static Rate inForce(List<Rate> rates, LocalDate date) {
